const m = (nom, suite, de, vers) => ({ nom: `nuit-${nom}`, suite, de, vers });
// Une constante numérique de la forme `<prefixe><valeur>;` : une mutation vers le haut, une vers le bas.
const borne = (nom, suite, prefixe, valeur, plus = valeur + 1, moins = valeur - 1) => [
  m(`${nom}-plus`, suite, `${prefixe}${valeur};`, `${prefixe}${plus};`),
  m(`${nom}-moins`, suite, `${prefixe}${valeur};`, `${prefixe}${moins};`),
];
// Une liste de mots : une mutation par mot retiré.
const sansMot = (nom, suite, prefixe, mots) => mots.map(mot => m(
  `${nom}-sans-${mot}`, suite, `${prefixe} [${mots.map(x => `'${x}'`).join(', ')}];`,
  `${prefixe} [${mots.filter(x => x !== mot).map(x => `'${x}'`).join(', ')}];`,
));

